def put(id,title,category,what,how,inputs,outputs,source,locator,kind='legacy',type='data',parent=None,next=None):
    what=what.replace('Решения о React-прототипе в эту карту не переносятся.','Принятые интервалы сохраняют связь с пачкой и разрезом.')
    what=what.replace('Это не набор стадий текущего интерфейса.','Направление профиля и происхождение интервалов сохраняют смысл построения.')
    what=what.replace('Шаблоны источников не ограничиваются тремя листами текущего UI.','Виды паспортов, масштабы и оформление описываются руководствами.')
    n=by.get(id)
    if n is None:
        n={'id':id,'type':type,'categoryId':category,'parentId':parent or category,'keywords':[]};nodes.append(n);by[id]=n
    n.update(title=title,summary=what.split('. ')[0]+'.',scope='domain',knowledgeBasis=kind,evidence=evidence(source,locator))
    if parent:n['parentId']=parent
    n['explanation']={'what':what,'why':'Позволяет проследить входы, действия и результат: '+title.lower()+'. Границы из источника сохраняются при передаче соседнему процессу.',
      'how':how.split('|'),'participants':{'interpretation':['Геолог и геофизик проверяют источники и вывод.'],'planning':['Геолог, инженер по запасам и моделист проверяют исходные данные и метод.'],'production':['Технолог и диспетчер работают с объектом на выбранную дату.'],'monitoring':['Диспетчер и лабораторный специалист проверяют замеры и пробы.'],'maintenance':['Механик и мастер РВР различают оборудование и работы на скважине.'],'accounting':['Технолог и аналитик сверяют факты за выбранный период.'],'management':['Специалист предметной области и ответственный за требования уточняют основание.']}.get(category,['Специалист предметной области проверяет объект и происхождение данных.']),
      'inputs':inputs.split('|'),'outputs':outputs.split('|'),'next':next or 'Результат передают связанному процессу с исходным контекстом. Неизвестные правила не восстанавливаются по сходству названий.',
      'example':'Учебный пример: для «'+title+'» показан один набор входов и отдельный результат. Это иллюстрация процесса, а не утверждённые производственные данные или численная методика.'}
    n['featured']=type=='data'
    return n
def link(a,t,b,label,description=None,sources=None,locator=None):
    found=next((e for e in edges if (e['source'],e['type'],e['target'])==(a,t,b)),None)
    if not found:
        found={'id':f'e-memory-{a}-{t}-{b}','source':a,'type':t,'target':b};edges.append(found)
    found.update(label=label,description=description or 'По источниковой памяти: '+label+'. Это предметная зависимость, не заявление об автоматическом обмене или SQL FK.',relationScope='domain',evidence=evidence(sources,locator or label) if sources else by[a]['evidence'][:2])

