# Curated input/output routes. Each source flow becomes an inspectable card and learning step.
flow_io={1:(['well','trajectory','core','alpha-source-record'],['composite-data']),2:(['data-exchange'],['import-staging']),3:(['alpha-source-record','alpha-derived-curve'],['alpha-result']),4:(['alpha-result','ai-suggestion'],['accepted-result']),5:(['well','well-construction','alpha-result'],['passport']),6:(['section-profile','source-contacts'],['geological-section','rhythm-excluded']),7:(['reserve-block','cutoff-limits','accepted-result'],['reserve-calculation']),8:(['composite-data'],['geological-model-2d','geological-model-3d']),9:(['configuration-event'],['as-of-plan']),10:(['well-membership','transport-graph'],['actual-regime']),11:(['control-point','import-staging'],['operating-measurements']),12:(['shutdown'],['shift-log']),13:(['solution-sample','import-staging'],['chemistry']),14:(['acid-tank'],['acid-balance']),15:(['pump','motor'],['pump-assembly','installation']),16:(['repair-order','well'],['repair-stage']),17:(['psv-project','actual-regime','chemistry'],['saved-state','forecast']),18:(['as-of-plan','reserve-calculation','saved-state','production-report'],['analytics-selection','decision'])}
flow_nodes=[]
for line in (MEM/'system/cross-module-flows.md').read_text(encoding='utf-8').splitlines():
    if not re.match(r'\| F\d\d\.',line):continue
    cells=[c.strip() for c in line.strip('|').split('|')];num=int(cells[0][1:3]);id=f'flow-f{num:02}'
    title=cells[0][5:];seq=cells[1];facts=re.sub(r'\[([^]]+)\]\([^)]+\)',r'\1',cells[2])
    src=' '.join(dict.fromkeys(x.lower() for x in re.findall(r'\b[DV]\d{3}\b',cells[2]))) or 'd038'
    cat='research' if num<=2 else 'interpretation' if num<=5 else 'planning' if num<=8 or num==17 else 'production' if num<=10 else 'monitoring' if num<=13 else 'accounting' if num==14 else 'maintenance' if num<=16 else 'management'
    inp,out=flow_io[num]
    put(id,title,cat,seq+'. '+facts,seq.replace(' → ','|'),'|'.join(by[x]['title'] for x in inp),'|'.join(by[x]['title'] for x in out),src,f'F{num:02}: system/cross-module-flows.md; '+facts[:350],'requirement' if num==4 else 'legacy','process')
    for x in inp:link(id,'uses',x,'Вход: '+by[x]['title'])
    for x in out:link(id,'produces',x,'Выход: '+by[x]['title'])
    flow_nodes.append(id)
assert len(flow_nodes)==18

